command:
$ErrorActionPreference = 'Continue'
# #997 MIGRATION — MIG-14. Soak telemetry, scaffolding removal, and the state HERMES is left in.
#
# The soak settled the escalation question against escalation. From a 68 C baseline the card reached
# the 85 C abort in about 59 seconds of continuous work, rising ~2-3 C per iteration with no plateau,
# while decode throughput barely moved (35.21 -> 34.80 tok/s). Performance was never the limit; heat
# was. #997 section 8 permits evaluating 200 W only after the 150 W configuration passes its thermal
# check, and a run that aborts on the thermal rule has not passed one. So no 200 W step is attempted
# and none is recommended: raising the cap by a third would add heat to a card that already cannot
# shed what 150 W produces. The constraint is airflow, not the power limit.
#
# Nothing needs restoring from the soak: the cap was never raised. This step removes the two one-shot
# tasks this lane created so the machine is left with exactly ONE Ollama-related scheduled task.

$smi = 'C:\Windows\System32\nvidia-smi.exe'
$P40 = 'GPU-4f7d4396-9304-d12f-7e9b-7f04d1236fc2'
$tele = 'D:\HermesServices\ollama\_install\soak150-telemetry.csv'

Write-Output '--- SOAK-TELEMETRY-SUMMARY ---'
$rows = Get-Content $tele -ErrorAction SilentlyContinue | Where-Object { $_ -match ',' }
Write-Output "samples=$($rows.Count)"
if ($rows.Count -gt 0) {
    $parsed = $rows | ForEach-Object {
        $f = $_ -split ',\s*'
        [pscustomobject]@{ temp = [double]$f[1]; power = [double]$f[2]; util = [double]$f[3]; mem = [double]$f[4]; sm = $f[5]; throttle = $f[6] }
    }
    $loaded = $parsed | Where-Object { $_.util -gt 50 }
    Write-Output "temp_start=$($parsed[0].temp) temp_max=$(($parsed.temp | Measure-Object -Maximum).Maximum) temp_end=$($parsed[-1].temp)"
    Write-Output "power_max=$(($parsed.power | Measure-Object -Maximum).Maximum)W power_mean_under_load=$(if ($loaded) { [math]::Round(($loaded.power | Measure-Object -Average).Average, 1) } else { 'UNKNOWN' })W"
    Write-Output "sm_clock_min_under_load=$(if ($loaded) { ($loaded.sm | Sort-Object { [int]$_ } | Select-Object -First 1) } else { 'UNKNOWN' }) sm_clock_max=$(($parsed.sm | Sort-Object { [int]$_ } | Select-Object -Last 1))"
    Write-Output "throttle_reasons_seen=$(($parsed.throttle | Sort-Object -Unique) -join ' | ')"
    Write-Output '--- SOAK-SAMPLES (every 4th) ---'
    for ($i = 0; $i -lt $rows.Count; $i += 4) { $rows[$i] }
}

Write-Output '--- THERMAL-LIMITS-FOR-THE-RECORD ---'
& $smi -i $P40 -q | Select-String -Pattern 'GPU Slowdown Temp|GPU Shutdown Temp' | ForEach-Object { $_.Line.Trim() }
Write-Output '--- ECC-FINAL (like-for-like) ---'
& $smi -i $P40 -q -d ECC | Select-String -Pattern 'Ecc Mode|Current|Pending|Volatile|Aggregate|Total' | Select-Object -First 20 | ForEach-Object { $_.Line.Trim() }

Write-Output '--- REMOVE-LANE-SCAFFOLDING ---'
foreach ($t in @('WilliamOS-MIG-997-FetchOllama', 'WilliamOS-MIG-997-Soak150')) {
    if (Get-ScheduledTask -TaskName $t -ErrorAction SilentlyContinue) {
        Unregister-ScheduledTask -TaskName $t -Confirm:$false
        Write-Output "removed one-shot task $t"
    }
}
Write-Output 'ollama-related scheduled tasks now:'
Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskName -match 'Ollama|MIG-997' } |
    ForEach-Object { "  task=$($_.TaskName) state=$($_.State)" }

Write-Output '--- FINAL-STATE ---'
Write-Output "task_state=$((Get-ScheduledTask -TaskName 'WilliamOS-HERMES-Ollama').State)"
Get-Process -Name 'ollama*' -ErrorAction SilentlyContinue | ForEach-Object { "process pid=$($_.Id) path=$($_.Path)" }
Get-NetTCPConnection -LocalPort 11434 -State Listen -ErrorAction SilentlyContinue | Select-Object LocalAddress, LocalPort | Format-Table -AutoSize | Out-String -Width 60
try {
    $t = Invoke-RestMethod 'http://127.0.0.1:11434/api/tags' -TimeoutSec 15
    Write-Output "api_models=$($t.models.Count) list=$(($t.models.name | Sort-Object) -join ',')"
} catch { Write-Output "api_ERR=$($_.Exception.Message)" }
Write-Output "containers_named_ollama=$((docker ps -a --filter name=ollama --format '{{.Names}}' 2>&1) -join ',')"
docker ps --format '{{.Names}}|{{.Status}}' 2>&1
Write-Output '--- GPU-FINAL ---'
& $smi --query-gpu=uuid,name,driver_model.current,power.limit,power.default_limit,temperature.gpu,power.draw,memory.used --format=csv,noheader
Write-Output '--- MODEL-LIBRARY-FINAL ---'
$b = Get-ChildItem 'D:\HermesData\ollama\models\blobs' -File | Measure-Object -Sum Length
Write-Output "blobs=$($b.Count) bytes=$($b.Sum)"
Get-ChildItem 'D:\HermesData\ollama\models\manifests' -Recurse -File | ForEach-Object { "manifest=$($_.FullName.Substring(38))" }
Write-Output '--- G-STORE-UNTOUCHED ---'
$g = Get-ChildItem 'G:\HermesData\ollama\models\blobs' -File -ErrorAction SilentlyContinue | Measure-Object -Sum Length
Write-Output "G blobs=$($g.Count) bytes=$($g.Sum)  (expected 12 / 7180381648 -- this lane never wrote here)"
Write-Output '--- FILE-DIGESTS-FINAL ---'
foreach ($f in @('C:\HermesLab\hermes\docker-compose.yml', 'C:\HermesLab\hermes\start-hermes.ps1',
        'C:\HermesLab\hermes\ollama-service\hermes-ollama-service.ps1',
        'C:\HermesLab\hermes\ollama-service\install-hermes-ollama-service.ps1')) {
    Write-Output "$f sha256=$((Get-FileHash $f -Algorithm SHA256).Hash.ToLower())"
}
Get-ChildItem 'C:\HermesLab\hermes\_997-rollback' -File | ForEach-Object { "rollback $($_.Name) sha256=$((Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLower())" }
Write-Output '--- RC ---'
